(()=>{'use strict';
const D=JSON.parse(document.getElementById('curriculum').textContent),KEY='mirae.learning.v1';
const $=id=>document.getElementById(id),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lessons=new Map(D.lessons.map(l=>[l.id,l])),questions=new Map(D.lessons.flatMap(l=>l.questions.map(q=>[q.id,{...q,lesson:l.id}])));
const empty=()=>({version:1,name:'',done:{},notes:{},scores:{},history:[],active:null,last:1});
let state=empty(),storageOK=true,view='home',currentLesson=1,currentModule=0,toastTimer,finishing=false;
function checkAttempt(a){if(!a)return null;if(!['practice','module','final'].includes(a.kind)||!Array.isArray(a.items)||a.items.length<1||a.items.length>140||!Number.isFinite(a.end)||!Number.isFinite(a.start)||a.end<a.start||a.end-a.start>86400000||typeof a.id!=='string')return null;
 const ids=new Set();for(const x of a.items){const q=questions.get(x.qid);if(!q||ids.has(x.qid)||!Array.isArray(x.options)||x.options.length!==3||new Set(x.options).size!==3||!x.options.every(o=>q.options.includes(o)))return null;ids.add(x.qid);if(x.answer!==null&&!q.options.includes(x.answer))return null;}
 if(typeof a.title!=='string'||typeof a.name!=='string'||!Number.isFinite(a.lastSeen)||a.lastSeen<a.start)return null; if(a.kind==='practice'&&!lessons.has(a.scope))return null;if(a.kind==='module'&&!D.modules.some(m=>m.id===a.scope))return null;return a;}
function parseState(raw){const s=JSON.parse(raw);if(s.version!==1)throw Error('version');const out=empty();out.name=typeof s.name==='string'?s.name.slice(0,100):'';out.last=lessons.has(s.last)?s.last:1;
 for(const l of D.lessons){out.done[l.id]=s.done?.[l.id]===true;out.notes[l.id]=typeof s.notes?.[l.id]==='string'?s.notes[l.id].slice(0,5000):'';const score=s.scores?.[l.id];if(Number.isInteger(score)&&score>=0&&score<=2)out.scores[l.id]=score;}
 out.active=checkAttempt(s.active);out.history=Array.isArray(s.history)?s.history.filter(r=>checkAttempt(r)&&Number.isFinite(r.finished)).slice(-100):[];return out;}
try{const raw=localStorage.getItem(KEY);if(raw)state=parseState(raw);}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('c-storage').hidden=storageOK;$('c-storage').textContent='Saqlash ishlamayapti yoki oldingi ma’lumot o‘qilmadi. Bu sessiyada ishlashingiz mumkin. Natijalarni eksport qiling; brauzer yopilsa so‘nggi ish yo‘qolishi mumkin.';}
if(!storageOK){$('c-storage').hidden=false;$('c-storage').textContent='Oldingi ma’lumot o‘qilmadi yoki saqlash cheklangan. Natijalarni eksport qilib boring.';}
function notify(s){$('c-toast').textContent=s;$('c-toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('c-toast').style.display='none',3500);}
const btn=(text,action,id='',primary=false)=>`<button class="c-btn ${primary?'primary':''}" data-act="${action}" data-id="${h(id)}">${h(text)}</button>`;
const learned=id=>state.done[id]&&state.scores[id]===2;
function sidebar(){const n=D.lessons.filter(l=>learned(l.id)).length;$('c-progress').value=n;$('c-progress-count').textContent=`${n} / 70`;$('c-modules').innerHTML=D.modules.map(m=>`<button class="c-side-btn ${currentModule===m.id?'selected':''}" data-mod="${m.id}"><b>${String(m.id).padStart(2,'0')} · ${h(m.title)}</b><span>${m.end-m.start+1}</span></button>`).join('');}
function resume(){const a=state.active;$('c-resume').innerHTML=a&&view!=='exam'?`<div class="c-notice c-info">Davom etayotgan sinov: <b>${h(a.title)}</b>. Vaqt sahifa yopilsa ham davom etadi. ${btn('Davom etish','resume')}</div>`:'';}
function render(html,kind){view=kind;$('c-view').innerHTML=html;sidebar();resume();}
function go(route){location.hash=route;if(location.hash==='#'+route)routeView();}
function showClub(){if(!document.getElementById('math-app').hidden&&typeof exam!=='undefined'&&exam&&!exam.finished&&screens.exam.classList.contains('active')){notify('Matematika mashqi vaqti davom etmoqda.');}
 $('club').hidden=false;$('math-app').hidden=true;document.querySelectorAll('[data-global]').forEach(b=>b.classList.toggle('active',b.dataset.global==='club'));}
function routeView(){showClub();const parts=location.hash.slice(1).split('/'),n=Number(parts[1]);if(parts[0]==='lesson'&&lessons.has(n))lessonPage(n);else if(parts[0]==='module'&&D.modules.some(m=>m.id===n))modulePage(n);else if(parts[0]==='exam'&&state.active)examPage();else if(parts[0]==='results')resultsPage();else if(parts[0]==='result'&&state.history.some(r=>r.id===parts[1]))resultPage(parts[1]);else if(parts[0]==='guide')guide();else home();window.scrollTo(0,0);$('c-main').focus({preventScroll:true});}
function home(){currentModule=0;const total=D.lessons.filter(l=>learned(l.id)).length;render(`<p class="c-eyebrow">MIRAE · IT TO‘GARAGI</p><section class="c-hero"><div><h1>Bugun bir qadam.<br>Ertaga yangi imkoniyat.</h1><p class="c-muted">Kompyuter buyruqlaridan birinchi loyihangizgacha. O‘qing, amalda bajaring va bilimni tekshiring — o‘z tezligingizda.</p><div class="c-actions">${btn('O‘rganishni davom ettirish →','lesson',state.last,true)}${btn('Natijalarim','results')}</div><div class="c-stats"><span><b>7</b> modul</span><span><b>70</b> mavzu</span><span><b>${total}</b> o‘zlashtirilgan</span></div></div><div class="c-hero-art" aria-hidden="true"><img src="data:image/png;base64," alt=""></div></section><div class="c-toolbar"><div><h2>O‘quv dasturingiz</h2><span class="c-muted">Boshlang‘ichdan amaliy loyihagacha</span></div><label><span class="c-eyebrow">MAVZU QIDIRISH</span><br><input id="c-search" class="c-input" placeholder="Masalan: Python, fayl, Word" type="search"></label></div><div id="c-catalog"></div><section class="c-block" style="margin-top:24px"><h2>Bilimni birlashtiring</h2><p>Yakuniy nazariy sinov: har moduldan 5 ta, jami 35 savol · 50 daqiqa · tavsiya etilgan chegara 70%. Amaliy loyiha ustoz tomonidan alohida rubrika bilan baholanadi.</p>${btn('Yakuniy sinov shartlari →','start-final')}</section>`,'home');catalog('');$('c-search').addEventListener('input',e=>catalog(e.target.value));}
function catalog(term){term=term.trim().toLocaleLowerCase();if(term){const found=D.lessons.filter(l=>(l.title+' '+l.body).toLocaleLowerCase().includes(term));$('c-catalog').innerHTML=`<p class="c-muted">${found.length} ta mavzu topildi</p><div class="c-list">${found.length?found.map(row).join(''):'<div class="c-empty">Mavzu topilmadi. Boshqa so‘z bilan qidiring.</div>'}</div>`;return;}
 $('c-catalog').innerHTML='<div class="c-grid">'+D.modules.map(m=>{const all=D.lessons.filter(l=>l.module===m.id),done=all.filter(l=>learned(l.id)).length;return `<article class="c-card"><div class="c-card-top"><span class="c-number">MODUL ${String(m.id).padStart(2,'0')}</span><span class="c-badge">${h(m.tag)}</span></div><h2>${h(m.title)}</h2><p>${h(m.description)}</p><progress value="${done}" max="${all.length}" aria-label="${h(m.title)} taraqqiyoti"></progress><div class="c-card-foot"><span>${done}/${all.length} mavzu · ${m.start}–${m.end}</span>${btn('Ochish →','module',m.id)}</div></article>`}).join('')+'</div>';}
function row(l){return `<button class="c-lesson-row" data-act="lesson" data-id="${l.id}"><span class="c-number">${String(l.id).padStart(2,'0')}</span><span class="c-row-main"><strong>${h(l.title)}</strong><small>${l.minutes} daqiqa · izoh + amaliyot + 2 savol</small></span><span class="c-done">${learned(l.id)?'✓ O‘zlashtirildi':state.done[l.id]?'Amaliy ish ✓':'→'}</span></button>`;}
function modulePage(id){currentModule=id;const m=D.modules.find(x=>x.id===id),list=D.lessons.filter(l=>l.module===id);render(`<div class="c-breadcrumb"><button data-go="home">Barcha modullar</button> / ${String(id).padStart(2,'0')}</div><p class="c-eyebrow">${h(m.tag)} · ${list.length} MAVZU</p><h1>${h(m.title)}</h1><p class="c-muted">${h(m.description)}. Tavsiya: mavzularni ketma-ket o‘ting. Har dars — 10 daqiqa tushunish, 25 daqiqa amaliyot, 10 daqiqa tekshirish; loyiha darslari 60 daqiqa.</p><div class="c-actions">${btn('Modul imtihoni','start-module',id,true)}${btn('Baholash mezonlari','rubric',id)}</div><div class="c-list" style="margin-top:26px">${list.map(row).join('')}</div>`,'module');}
function lessonPage(id){currentLesson=id;state.last=id;save();const l=lessons.get(id);currentModule=l.module;render(`<div class="c-breadcrumb"><button data-mod="${l.module}">${h(D.modules[l.module-1].title)}</button> / ${id}-mavzu</div><p class="c-eyebrow">${id} / 70 · ${l.minutes} DAQIQA</p><h1>${h(l.title)}</h1><div class="c-steps"><span>01 Tushuning</span><span>02 Sinab ko‘ring</span><span>03 O‘zingiz bajaring</span><span>04 Tekshiring</span></div><div class="c-lesson-layout"><div><section class="c-block"><h2>Nimani o‘rganasiz?</h2><p>${h(l.body)}</p><h3>Ko‘rib chiqing va izohlang</h3><pre class="c-code">${h(l.example)}</pre><small class="c-muted">${l.module===5?'Bu psevdokod: Flowgorithm shakllariga aylantiring.':l.module===1||l.module===2?'Buyruqlarni faqat MiraeLab sinov papkasida bajaring.':'Misolni o‘z muhitingizda sinang.'}</small><ol><li>Natijani avval taxmin qiling.</li><li>Misolni bajaring va taxmin bilan solishtiring.</li><li>Bitta qiymatni o‘zgartirib, farqini tushuntiring.</li></ol></section><section class="c-block"><p class="c-eyebrow">AMALIY TOPSHIRIQ</p><h2>Endi navbat sizga</h2><p>${h(l.task)}</p><div class="c-notice c-info"><b>Qabul mezoni:</b> ${h(l.criterion)}</div><h3>O‘zingizni tekshiring</h3><ul><li>Oddiy misolda kutilgan natija chiqdimi?</li><li>Bo‘sh yoki noto‘g‘ri kirishda nima bo‘ldi?</li><li>Natijani ustozga fayl yoki ekran bilan ko‘rsata olasizmi?</li></ul><label class="c-check"><input type="checkbox" id="c-task" ${state.done[id]?'checked':''}><span>Amaliy ishni bajardim va mezon bilan tekshirdim. <small>Bu shaxsiy belgi; ustoz bahosi emas.</small></span></label></section><div class="c-actions">${id>1?btn('← Oldingi mavzu','lesson',id-1):''}${id<70?btn('Keyingi mavzu →','lesson',id+1):btn('Yakuniy sinov','start-final')}</div></div><aside class="c-notebook"><section class="c-block"><p class="c-eyebrow">BILIMNI TEKSHIRISH</p><h2>2 savolli mashq</h2><p>Javob va izohlar topshirgandan keyin ochiladi. Qayta urinib o‘rganishingiz mumkin.</p><p><b>Eng yaxshi natija: ${state.scores[id]??'—'} / 2</b></p>${btn('Testni boshlash','start-practice',id,true)}<p style="margin-top:16px" class="c-muted">O‘zlashtirish: amaliy ish belgisi + 2/2 natija.</p></section><section class="c-block"><label for="c-note"><h2>O‘quv kundaligi</h2></label><p class="c-muted">Nima ishladi? Qaysi xatoni tuzatdingiz? Ish fayli qayerda?</p><textarea id="c-note" class="c-input c-note" maxlength="5000" placeholder="Misol: 60 chegarasini tekshirdim…">${h(state.notes[id]||'')}</textarea><small id="c-note-status" class="c-muted" role="status">Shu Windows hisobi / brauzerda saqlanadi.</small></section></aside></div>`,'lesson');
 $('c-task').addEventListener('change',e=>{state.done[id]=e.target.checked;save();sidebar();notify('Amaliy ish belgisi saqlandi.');});$('c-note').addEventListener('input',e=>{state.notes[id]=e.target.value;save();$('c-note-status').textContent=storageOK?'Qayd saqlandi.':'Saqlanmadi — matnni nusxalab oling.';});}
function shuffled(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
async function ask(title,text,fields=''){const d=$('c-dialog');if(d.open)return false;$('c-dialog-title').textContent=title;$('c-dialog-text').textContent=text;$('c-dialog-fields').innerHTML=fields;d.returnValue='cancel';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
async function start(kind,id){if(typeof exam!=='undefined'&&exam&&!exam.finished&&screens.exam.classList.contains('active')){notify('Avval matematika mashqini yakunlang.');return;}if(state.active){notify('Avval davom etayotgan sinovni yakunlang.');go('exam');return;}
 let pool,title,minutes;if(kind==='practice'){pool=lessons.get(id).questions;title=lessons.get(id).title;minutes=8;}else if(kind==='module'){pool=D.lessons.filter(l=>l.module===id).flatMap(l=>l.questions);title=D.modules[id-1].title+' · modul imtihoni';minutes=Math.ceil(pool.length*1.5);}else{pool=D.modules.flatMap(m=>shuffled(D.lessons.filter(l=>l.module===m.id)).slice(0,5).map(l=>shuffled(l.questions)[0]));title='Yakuniy nazariy sinov';minutes=50;}
 const ok=await ask(title,`${pool.length} savol · ${minutes} daqiqa. ${kind==='practice'?'Mashq.':'O‘quv imtihoni; tavsiya etilgan o‘tish chegarasi 70%.'} Natija yakunlaganda ochiladi. Sahifani yopish vaqtni to‘xtatmaydi. Bu lokal natija rasmiy sertifikat emas.`,`<label for="c-student">O‘quvchi ismi</label><input id="c-student" class="c-input" maxlength="100" required value="${h(state.name)}" autocomplete="name">`);if(!ok)return;
 const name=$('c-student').value.trim();if(!name){notify('Ismni kiriting.');return;}state.name=name;const now=Date.now();state.active={id:now.toString(36)+'-'+Math.random().toString(36).slice(2,8),kind,scope:id||0,title,name,start:now,end:now+minutes*60000,lastSeen:now,items:shuffled(pool).map(q=>({qid:q.id,options:shuffled(q.options),answer:null}))};save();go('exam');}
function effectiveNow(a){return Math.max(Date.now(),a.lastSeen||0);}
function examPage(){const a=state.active;if(!a){go('results');return;}currentModule=a.kind==='module'?a.scope:0;
 render(`<div class="c-exam-bar"><div><span class="c-eyebrow">${a.kind==='practice'?'MAVZU MASHQI':'O‘QUV IMTIHONI'}</span><h2 style="margin:4px 0">${h(a.title)}</h2><small>${h(a.name)} · <span id="c-answered"></span></small></div><span class="c-clock" id="c-clock" role="timer" aria-label="Qolgan vaqt"></span></div><p class="c-muted">Bitta javobni tanlang. Yakunlashgacha javobni o‘zgartirish mumkin. Belgilanmagan javob 0 ball.</p><div id="c-exam-questions">${a.items.map((x,i)=>{const q=questions.get(x.qid);return `<fieldset class="c-question"><legend>${i+1}. ${h(q.prompt)}</legend>${x.options.map((o,j)=>`<label class="c-option"><input type="radio" name="q${i}" data-answer="${i}" value="${j}" ${x.answer===o?'checked':''}><span>${h(o)}</span></label>`).join('')}</fieldset>`}).join('')}</div><div class="c-actions">${btn('Sinovni yakunlash','finish','',true)}${btn('Darslarga qaytish','home')}</div><p class="c-muted">Darsga qaytsangiz vaqt davom etadi. Savollar lokal o‘quv bankidan; mustaqil hal qilishni mashq qiling.</p>`,'exam');updateTimer();}
function updateTimer(){const a=state.active;if(!a)return;const now=effectiveNow(a);a.lastSeen=now;if(now>=a.end){finish(true);return;}const left=Math.ceil((a.end-now)/1000);if(view==='exam'&&$('c-clock')){$('c-clock').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');$('c-clock').style.color=left<60?'#b3352d':'';$('c-answered').textContent=`${a.items.filter(x=>x.answer!==null).length} / ${a.items.length} belgilandi`;}}
async function finish(auto=false){if(!state.active||finishing)return;finishing=true;const a=state.active;if(!auto){const skip=a.items.filter(x=>x.answer===null).length;const ok=await ask('Sinovni yakunlaysizmi?',`${skip} ta savol belgilanmagan. Tasdiqlangandan so‘ng javoblar o‘zgarmaydi.`);if(!ok){finishing=false;updateTimer();return;}}
 if(state.active?.id!==a.id){finishing=false;return;}const now=effectiveNow(a);const result={...a,finished:Math.min(now,a.end),auto:auto||now>=a.end};state.history.push(result);state.history=state.history.slice(-100);if(a.kind==='practice'){const score=a.items.filter(x=>x.answer===questions.get(x.qid).correct).length;state.scores[a.scope]=Math.max(state.scores[a.scope]||0,score);}state.active=null;finishing=false;save();go('result/'+result.id);}
function score(r){return r.items.filter(x=>x.answer===questions.get(x.qid).correct).length;}
function resultPage(id){const r=state.history.find(x=>x.id===id);if(!r){resultsPage();return;}const n=score(r),pct=Math.round(n/r.items.length*100),skip=r.items.filter(x=>x.answer===null).length;currentModule=0;render(`<p class="c-eyebrow">${r.kind==='practice'?'MASHQ TAHLILI':'O‘QUV IMTIHONI TAHLILI'}</p><h1>${h(r.title)}</h1><p class="c-muted">${h(r.name)} · ${new Date(r.finished).toLocaleString('uz-UZ')} ${r.auto?'· Vaqt tugadi':''}</p><div class="c-block"><div class="c-result-score">${pct}% <span style="font-size:17px">${n} / ${r.items.length}</span></div><p>${n} to‘g‘ri · ${r.items.length-n-skip} xato · ${skip} belgilanmagan · ${Math.max(0,Math.round((r.finished-r.start)/60000))} daqiqa</p><p><b>${r.kind==='practice'?(n===r.items.length?'Mavzu tekshiruvi bajarildi.':'Izohlarni o‘qib, qayta mashq qiling.'):(pct>=70?'70% nazariy chegara bajarildi.':'Takrorlash tavsiya etiladi: 70% chegaraga hali yetilmadi.')}</b></p><p class="c-muted">Amaliy topshiriq va loyiha ustoz tomonidan alohida tekshiriladi.</p><div class="c-actions">${btn('Natijani yuklab olish','export-result',r.id)}${btn('Chop etish','print')}${btn('Barcha natijalar','results')}</div></div><div class="c-toolbar"><h2>Javoblar va tavsiyalar</h2><label class="c-check"><input id="c-wrong-only" type="checkbox">Faqat takrorlash keraklari</label></div><div id="c-reviews">${r.items.map((x,i)=>{const q=questions.get(x.qid),ok=x.answer===q.correct;return `<article class="c-block c-review ${ok?'ok':''}" data-correct="${ok}"><p class="c-eyebrow">${i+1}-SAVOL · ${ok?'TO‘G‘RI':x.answer===null?'BELGILANMAGAN':'QAYTA KO‘RING'}</p><h3>${h(q.prompt)}</h3><p>Siz: ${h(x.answer??'Belgilanmagan')}<br><b>To‘g‘ri: ${h(q.correct)}</b></p><small>${h(q.explain)}</small><div class="c-actions">${btn(q.lesson+'-mavzuni takrorlash →','lesson',q.lesson)}</div></article>`}).join('')}</div>`,'result');$('c-wrong-only').addEventListener('change',e=>document.querySelectorAll('#c-reviews article').forEach(x=>x.hidden=e.target.checked&&x.dataset.correct==='true'));}
function resultsPage(){currentModule=0;render(`<p class="c-eyebrow">SHAXSIY O‘QUV JURNALI</p><h1>Natijalar va qaydlar</h1><p class="c-muted">Shu Windows hisobi yoki brauzer profiliga tegishli lokal yozuvlar. Oxirgi 100 urinish saqlanadi. Boshqa qurilmaga ko‘chirishdan oldin JSON zaxira oling. Bu yozuvlar tahrirlanishi mumkin; rasmiy baholash uchun serverdagi “Testlar” bo‘limidan foydalaning.</p><div class="c-actions">${btn('Zaxira yuklab olish','export')}${btn('Zaxiradan tiklash','import')}${btn('Chop etish','print')}</div><input type="file" id="c-import" accept="application/json,.json" hidden><section class="c-block" style="margin-top:24px"><h2>Sinovlar tarixi</h2>${state.history.length?'<div class="c-table-wrap"><table class="c-table"><thead><tr><th>Sana</th><th>Sinov / o‘quvchi</th><th>Natija</th><th>Tahlil</th></tr></thead><tbody>'+[...state.history].reverse().map(r=>`<tr><td>${new Date(r.finished).toLocaleDateString('uz-UZ')}</td><td>${h(r.title)}<br><small>${h(r.name)}</small></td><td>${score(r)} / ${r.items.length}</td><td>${btn('Ochish','result',r.id)}</td></tr>`).join('')+'</tbody></table></div>':'<div class="c-empty">Hali urinish yo‘q. Darsni ochib, mavzu testini bajaring.</div>'}</section><section class="c-block"><h2>Qayd yozilgan mavzular</h2><div class="c-list">${D.lessons.filter(l=>state.notes[l.id]).map(row).join('')||'<p class="c-muted">Dars ichidagi kundalikka yozilgan qaydlar shu yerda ko‘rinadi.</p>'}</div></section>`,'results');$('c-import').onchange=importState;}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function importState(e){const f=e.target.files[0];if(!f)return;if(state.active){notify('Avval faol sinovni yakunlang.');return;}if(f.size>2_000_000){notify('Zaxira 2 MB dan kichik bo‘lsin.');return;}let parsed;try{parsed=parseState(await f.text());}catch{notify('Yaroqli Mirae v1 zaxira fayli emas.');return;}
 if(await ask('Zaxiradan tiklash',`${parsed.history.length} urinish va qaydlar joriy lokal jurnalni ALMASHTIRADI. Avval joriy zaxirani yuklab olganingizga ishonch hosil qiling.`)){state=parsed;save();resultsPage();updateTimer();notify('Zaxira tiklandi.');}}
function guide(){currentModule=0;render(`<p class="c-eyebrow">O‘QUVCHI VA USTOZ UCHUN</p><h1>Qanday foydalaniladi?</h1><section class="c-block"><h2>Dars → amaliyot → tekshirish</h2><ol><li>Modulni tanlang va dars izohini o‘qing.</li><li>Misolni o‘z dasturingizda bajaring. Bu sahifa terminal kodini ishga tushirmaydi.</li><li>Amaliy topshiriqni qabul mezoni bilan tekshiring; faylni saqlang.</li><li>Ikki savolli testni bajaring. 2/2 + amaliy ish belgisi mavzuni o‘zlashtirilgan qiladi.</li><li>Modul oxirida imtihon va loyiha muhokamasini bajaring.</li></ol></section><section class="c-block"><h2>Ustozning baholash mezonlari</h2><p>Bu boshlang‘ich o‘quv dasturi. 45 daqiqalik mavzularni guruh tezligiga ko‘ra ikki darsga bo‘lish mumkin. Word va Excel modullari umumiy kirish darajasida; chuqur o‘zlashtirish qo‘shimcha mashq talab qiladi.</p><ul><li><b>30% — talab:</b> topshiriq maqsadi va qabul mezoni bajarilgan.</li><li><b>30% — ishlash:</b> asosiy natija to‘g‘ri va takror olinadi.</li><li><b>20% — tekshiruv:</b> normal, bo‘sh, chegara va xato holatlari.</li><li><b>10% — UI:</b> o‘qilish, aniq nomlar, klaviatura va xato xabarlari.</li><li><b>10% — izoh:</b> o‘quvchi o‘z ishini tushuntira oladi.</li></ul><p>Nazariy test loyiha bahosini almashtirmaydi. Kamchilik bo‘lsa qayta topshirish va aniq fikr bildirish tavsiya etiladi.</p></section><section class="c-block"><h2>Saqlash va imtihon chegaralari</h2><p>Materiallar offline ishlaydi. Qaydlar va natijalar bitta Windows/brauzer profilida lokal saqlanadi; qurilmalar o‘rtasida avtomatik sinxronlash yo‘q. Har o‘quvchiga alohida Windows hisobi tavsiya etiladi. Natijalar bo‘limidan JSON eksport qiling.</p><p>To‘garak testlari mustaqil o‘rganish uchun. Javob banki va lokal yozuvlar qurilmada mavjud; ular buzib bo‘lmaydigan rasmiy imtihon emas. Nazoratli baholashda desktop “Testlar” xizmatidan foydalaning. Soatni o‘zgartirishga qarshi server kafolati bu sahifada yo‘q.</p></section><section class="c-block"><h2>Favqulodda olib tashlash</h2><p>Windows ilovasida boshlang‘ich yoki Sozlamalar sahifasidagi <b>“Favqulodda olib tashlash”</b> tugmasidan foydalaning. Windows administrator tasdig‘i va favqulodda parol so‘raladi. Jarayon avval ilova o‘zgartirgan cheklovlarni tiklaydi, keyin xizmatni olib tashlaydi; tiklash xatosida fayl va zaxiralar saqlanadi.</p><p>Bu alohida HTML sahifa Windows xizmatini olib tashlamaydi. Administrator uchun yo‘riqnoma to‘liq paketning TOGARAK.md faylida.</p></section><section class="c-block"><h2>Rasmiy manbalar</h2><p>Versiyaga bog‘liq imkoniyatlarni o‘rnatilgan dastur yordamidan tekshiring.</p><ul><li>Microsoft Learn — Windows commands, PowerShell</li><li>Microsoft Support — Word va Excel yordam markazi</li><li>flowgorithm.org/documentation — shakllar va sikllar</li><li>docs.python.org/3/tutorial — Python qo‘llanmasi</li><li>docs.github.com/en/pages — GitHub Pages</li></ul></section>`,'guide');}
$('c-view').addEventListener('change',e=>{if(!e.target.matches('[data-answer]')||!state.active)return;const a=state.active;if(effectiveNow(a)>=a.end){finish(true);return;}const i=Number(e.target.dataset.answer),j=Number(e.target.value);if(a.items[i]&&j>=0&&j<3){a.items[i].answer=a.items[i].options[j];save();updateTimer();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.global){if(b.dataset.global==='math'){if(state.active){notify('Avval davom etayotgan sinovni yakunlang.');go('exam');return;}$('club').hidden=true;$('math-app').hidden=false;document.querySelectorAll('[data-global]').forEach(x=>x.classList.toggle('active',x===b));window.scrollTo(0,0);}else go(b.dataset.global==='guide'?'guide':'home');return;}if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.mod){go('module/'+b.dataset.mod);return;}const act=b.dataset.act,id=b.dataset.id;if(!act)return;
 switch(act){case'home':go('home');break;case'module':go('module/'+id);break;case'lesson':go('lesson/'+id);break;case'results':go('results');break;case'result':go('result/'+id);break;case'resume':go('exam');break;case'start-practice':start('practice',Number(id));break;case'start-module':start('module',Number(id));break;case'start-final':start('final',0);break;case'finish':finish();break;case'rubric':go('guide');break;case'print':window.print();break;case'export':download('Mirae-jurnal-'+new Date().toISOString().slice(0,10)+'.json',state);break;case'export-result':{const r=state.history.find(x=>x.id===id);download('Mirae-natija-'+id+'.json',{...r,correct:score(r),total:r.items.length,disclaimer:'Lokal o‘quv natijasi; rasmiy sertifikat emas.'});break;}case'import':$('c-import').click();break;}
});
window.addEventListener('hashchange',routeView);
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{state=parseState(e.newValue);if(view==='exam')examPage();else{sidebar();resume();}notify('Boshqa oynadagi jurnal o‘zgarishi yuklandi.');}catch{notify('Boshqa oynadagi yozuv yaroqsiz; joriy ish saqlanmoqda.');}});
window.addEventListener('pagehide',()=>{if(state.active){state.active.lastSeen=effectiveNow(state.active);save();}});
window.addEventListener('beforeunload',e=>{if(state.active){save();e.preventDefault();e.returnValue='';}});
setInterval(()=>{updateTimer();},1000);setInterval(()=>{if(state.active)save();},15000);
routeView();updateTimer();
})();
